class CircularDependencyError(Exception):
    pass


class DependencyResolver:
    def resolve(
        self, dependencies: dict[str, list[str]]
    ) -> list[list[str]]:
        tasks = set(dependencies)
        for required_tasks in dependencies.values():
            tasks.update(required_tasks)

        remaining = {
            task: set(dependencies.get(task, []))
            for task in tasks
        }
        stages: list[list[str]] = []

        while remaining:
            stage = sorted(
                task for task, requirements in remaining.items()
                if not requirements
            )

            if not stage:
                raise CircularDependencyError(
                    "Circular dependency detected"
                )

            stages.append(stage)
            completed = set(stage)

            for task in stage:
                del remaining[task]

            for requirements in remaining.values():
                requirements.difference_update(completed)

        return stages
